-- Arbeitsrecht Berufsbildung > Pflichten von Auszubildenden > Lernpflichten erfüllen (§ 13 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker die ihm gestellten Lernaufgaben erfüllen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG verpflichtet dazu"}, {"text": "Nein", "correct": false, "because": "Lernpflichten sind gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker die Teilnahme an Schulungen verweigern, wenn sie ihm nicht gefallen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG verlangt Mitwirkung bei der Ausbildung"}, {"text": "Ja", "correct": false, "because": "Verweigerung widerspricht den Pflichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Fachinformatiker verpflichtet, sich auf die IHK-Abschlussprüfung vorzubereiten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG umfasst die Prüfungsvorbereitung"}, {"text": "Nein", "correct": false, "because": "Vorbereitung ist Teil der Lernpflichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker selbst entscheiden, welche Programmiersprachen er lernen möchte?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG bindet ihn an den Ausbildungsplan"}, {"text": "Ja", "correct": false, "because": "Der Betrieb legt die Inhalte fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker auch außerhalb der Arbeitszeit lernen, wenn es erforderlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG fordert vollständige Erfüllung der Lernpflichten"}, {"text": "Nein", "correct": false, "because": "Lernen gehört zur Ausbildung"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Fachinformatiker zur Erfüllung seiner Lernpflichten?', 2, '[{"text": "§ 13 BBiG", "correct": true, "because": "Regelt die Pflichten des Auszubildenden"}, {"text": "§ 14 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Betriebs"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn er eine Lernaufgabe nicht versteht?', 3, '[{"text": "Den Ausbilder um Unterweisung bitten", "correct": true, "because": "§ 13 BBiG fordert aktive Mitwirkung"}, {"text": "Die Aufgabe ignorieren", "correct": false, "because": "Widerspricht den Pflichten"}, {"text": "Sofort kündigen", "correct": false, "because": "Zu radikal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tätigkeit gehört zu den Lernpflichten eines Fachinformatikers?', 3, '[{"text": "Erlernen von Programmiergrundlagen", "correct": true, "because": "Entspricht § 13 BBiG und dem Ausbildungsplan"}, {"text": "Kaffeekochen für das Team", "correct": false, "because": "Keine Lernpflicht"}, {"text": "Private Projekte verfolgen", "correct": false, "because": "Nicht betrieblich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer überwacht, ob ein Fachinformatiker seine Lernpflichten erfüllt?', 2, '[{"text": "Der Ausbilder", "correct": true, "because": "§ 14 BBiG verpflichtet ihn zur Kontrolle"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule ergänzt nur"}, {"text": "Der Auszubildende selbst", "correct": false, "because": "Er hat keine Überwachungspflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker seine Lernpflichten nicht erfüllt?', 3, '[{"text": "Er kann verwarnt oder gekündigt werden", "correct": true, "because": "Verstoß gegen § 13 BBiG kann Konsequenzen haben"}, {"text": "Der Betrieb übernimmt die Aufgaben", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Die IHK zahlt eine Strafe", "correct": false, "because": "IHK ist nicht verantwortlich"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben gehören zu den Lernpflichten eines Fachinformatikers gemäß § 13 BBiG?', 4, '[{"text": "Programmieren lernen", "correct": true, "because": "Teil des Ausbildungsplans"}, {"text": "Netzwerkkonzepte verstehen", "correct": true, "because": "Relevanter Ausbildungsinhalt"}, {"text": "Büro aufräumen", "correct": false, "because": "Keine Lernpflicht"}, {"text": "Vorbereitung auf die IHK-Prüfung", "correct": true, "because": "Pflicht zur Zielerreichung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Fachinformatiker bei Nichterfüllung seiner Lernpflichten?', 3, '[{"text": "Verwarnung durch den Betrieb", "correct": true, "because": "Mögliche Reaktion auf Pflichtverletzung"}, {"text": "Kündigung bei schwerem Verstoß", "correct": true, "because": "§ 22 BBiG erlaubt dies"}, {"text": "Automatische Beförderung", "correct": false, "because": "Nicht logisch"}, {"text": "Ausschluss von der Prüfung", "correct": false, "because": "Nicht direkt vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Fachinformatiker tun, um seine Lernpflichten nach § 13 BBiG zu erfüllen?', 4, '[{"text": "An Schulungen teilnehmen", "correct": true, "because": "Teil der Ausbildung"}, {"text": "Den Ausbildungsplan befolgen", "correct": true, "because": "Bindend gemäß § 13 BBiG"}, {"text": "Nur persönliche Interessen verfolgen", "correct": false, "because": "Nicht ausreichend"}, {"text": "Sich aktiv einbringen", "correct": true, "because": "Mitwirkung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterstützung kann ein Fachinformatiker erwarten, um seine Lernpflichten zu erfüllen?', 3, '[{"text": "Unterweisung durch den Ausbilder", "correct": true, "because": "§ 14 Abs. 1 BBiG garantiert dies"}, {"text": "Bereitstellung von Arbeitsmitteln", "correct": true, "because": "§ 14 Abs. 1 BBiG schreibt es vor"}, {"text": "Bezahlte Freizeit", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Zusätzliche Vergütung", "correct": false, "because": "Nicht Teil der Pflichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tätigkeiten verstoßen gegen die Lernpflichten eines Fachinformatikers?', 3, '[{"text": "Schulungen ignorieren", "correct": true, "because": "Widerspricht § 13 BBiG"}, {"text": "Programmieraufgaben lösen", "correct": false, "because": "Entspricht den Pflichten"}, {"text": "Berufsschule schwänzen", "correct": true, "because": "Verstoß gegen § 15 BBiG"}, {"text": "IHK-Prüfung vorbereiten", "correct": false, "because": "Teil der Pflichten"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Fachinformatiker muss sich aktiv an der Ausbildung beteiligen. b) Lernpflichten gelten nur während der Arbeitszeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beteiligung ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lernpflichten umfassen die Vorbereitung auf die IHK-Prüfung. b) Ein Fachinformatiker kann Lernaufgaben frei wählen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prüfung ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker muss den Ausbildungsplan einhalten. b) Lernpflichten gelten nur in der Berufsschule.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Plan ist bindend, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker darf Schulungen verweigern, wenn sie ihm nicht gefallen. b) Lernpflichten sind Teil des Ausbildungsvertrags.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Verweigerung ist unzulässig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Pflichten sind vertraglich"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker muss sich auch außerhalb der Arbeitszeit weiterbilden, wenn nötig. b) Lernpflichten enden mit der Probezeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Weiterbildung kann erforderlich sein, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

